import os
import sys
import tempfile
import webbrowser

# Check if URL was passed as command argument, e.g.: python qr.py https://moist-intrumorals.vercel.app/
if len(sys.argv) > 1:
    TARGET_URL = sys.argv[1]
    if not TARGET_URL.startswith("http://") and not TARGET_URL.startswith("https://"):
        TARGET_URL = "https://" + TARGET_URL
else:
    TARGET_URL = "https://moist-intrumorals.vercel.app/"

HTML_CONTENT = f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MOIST INTRAMURALS 2026-2027 | QR & URL Portal</title>
  <link href="https://fonts.googleapis.com/css2?family=Orbitron:wght@700;900&family=Poppins:wght@400;700;800&display=swap" rel="stylesheet">
  <style>
    * {{ box-sizing: border-box; margin: 0; padding: 0; }}
    body {{
      background: radial-gradient(circle at center, #36020c 0%, #0f0206 100%);
      color: #ffffff;
      font-family: 'Poppins', sans-serif;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 20px;
      text-align: center;
    }}
    .badge {{
      background: rgba(255, 215, 0, 0.1);
      border: 1.5px solid #ffd700;
      color: #ffd700;
      padding: 8px 20px;
      border-radius: 50px;
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 1px;
      margin-bottom: 20px;
    }}
    h1 {{
      font-family: 'Orbitron', sans-serif;
      font-size: 2.5rem;
      color: #ffd700;
      text-shadow: 0 0 20px rgba(255, 215, 0, 0.6);
      margin-bottom: 10px;
    }}
    p.sub {{
      font-size: 1.1rem;
      color: #e0b0b8;
      margin-bottom: 30px;
    }}
    .url-card {{
      background: rgba(0, 0, 0, 0.6);
      border: 2px solid #ffd700;
      border-radius: 16px;
      padding: 18px 30px;
      margin-bottom: 30px;
      box-shadow: 0 0 30px rgba(255, 215, 0, 0.3);
      max-width: 90%;
    }}
    .url-card label {{
      display: block;
      font-size: 0.85rem;
      color: #ffd700;
      letter-spacing: 1px;
      margin-bottom: 8px;
    }}
    .url-link {{
      font-family: 'Orbitron', sans-serif;
      font-size: 1.8rem;
      font-weight: 900;
      color: #ffffff;
      text-decoration: none;
      letter-spacing: 1px;
      word-break: break-all;
      transition: color 0.2s ease;
    }}
    .url-link:hover {{
      color: #ffd700;
    }}
    .qr-frame {{
      background: #ffffff;
      padding: 20px;
      border-radius: 24px;
      border: 4px solid #ffd700;
      box-shadow: 0 0 45px rgba(255, 215, 0, 0.7);
      margin-bottom: 25px;
      cursor: pointer;
      transition: transform 0.25s ease;
      display: inline-block;
    }}
    .qr-frame:hover {{
      transform: scale(1.04);
    }}
    .qr-img {{
      width: 420px;
      height: 420px;
      display: block;
    }}
    .hint {{
      font-size: 1rem;
      color: #ffd700;
      font-weight: 700;
      letter-spacing: 0.5px;
    }}
  </style>
</head>
<body>
  <div class="badge">MISAMIS ORIENTAL INSTITUTE OF SCIENCE AND TECHNOLOGY, INC.</div>
  <h1>MOIST INTRAMURALS 2026-2027</h1>
  <p class="sub">SCAN OR TYPE THE URL BELOW TO CLAIM YOUR BSIT FREE TICKET</p>

  <div class="url-card">
    <label>OFFICIAL WEBSITE SEARCHABLE URL:</label>
    <a href="{TARGET_URL}" target="_blank" class="url-link">{TARGET_URL}</a>
  </div>

  <div class="qr-frame" onclick="window.open('{TARGET_URL}', '_blank')">
    <img src="https://api.qrserver.com/v1/create-qr-code/?size=450x450&data={TARGET_URL}" alt="Scan QR Code" class="qr-img">
  </div>

  <p class="hint">POINT YOUR MOBILE CAMERA TO SCAN AND LAUNCH</p>
</body>
</html>"""

def main():
    temp_dir = tempfile.gettempdir()
    filepath = os.path.join(temp_dir, "moist_intramurals_qr.html")
    with open(filepath, "w", encoding="utf-8") as f:
        f.write(HTML_CONTENT)
    print("==========================================================")
    print("MOIST INTRAMURALS 2026-2027 QR CODE LAUNCHER")
    print(f"Target URL: {TARGET_URL}")
    print("Opening giant QR Code & URL portal in browser...")
    print("==========================================================")
    webbrowser.open(f"file://{filepath}")

if __name__ == "__main__":
    main()
